package com.franco.desco.adapter.in.web.sanitation;import com.franco.desco.application.sanitation.*;import com.franco.desco.application.shared.pagination.PageRequest;import com.franco.desco.domain.sanitation.SanitationModels;import org.springframework.stereotype.Component;import java.time.LocalDate;
@Component public class SanitationWebMapper{public SanitationCommands.ListCases list(int p,int t,String estado,String sev,Long predio,Long socio,Integer tipo,LocalDate desde,LocalDate hasta){return new SanitationCommands.ListCases(new PageRequest<>(p,t,new SanitationCommands.Filter(estado,sev,predio,socio,tipo,desde,hasta),null,null));}public SanitationResponses.Summary response(SanitationModels.Summary x){return new SanitationResponses.Summary(x.casoFitosanitarioId(),x.fechaDeteccion(),x.estadoCaso(),x.severidad(),x.plantasAfectadas(),x.cantidadEstimada(),x.codigoProblema(),x.problema(),x.parcelaCultivoId(),x.parcelaId(),x.parcelaNombre(),x.predioId(),x.predioCodigo(),x.predioNombre(),x.socioId(),x.numeroDocumento(),x.socioNombre(),x.evidencias());}public SanitationResponses.Detail response(SanitationModels.Detail x){var h=x.caso();return new SanitationResponses.Detail(new SanitationResponses.Header(h.casoFitosanitarioId(),h.parcelaCultivoId(),h.tipoProblemaId(),h.codigoProblema(),h.categoria(),h.problema(),h.visitaDeteccionId(),h.fechaDeteccion(),h.plantasAfectadas(),h.cantidadEstimada(),h.severidad(),h.estadoCaso(),h.observacion(),h.parcelaId(),h.parcelaNombre(),h.predioId(),h.predioCodigo(),h.predioNombre(),h.variedad()),x.tratamientos().stream().map(t->new SanitationResponses.Treatment(t.tratamientoId(),t.fechaHora(),t.visitaTecnicaId(),t.responsableEmpleadoId(),t.responsable(),t.tratamiento(),t.producto(),t.dosis(),t.unidadDosis(),t.observacion())).toList(),x.seguimientos().stream().map(s->new SanitationResponses.FollowUp(s.seguimientoId(),s.fechaHora(),s.visitaTecnicaId(),s.plantasAfectadas(),s.cantidadEstimada(),s.severidad(),s.resultado(),s.observacion())).toList(),x.archivos().stream().map(f->new SanitationResponses.File(f.archivoId(),f.nombreOriginal(),f.mimeType(),f.secureUrl(),f.categoria(),f.origenCaptura(),f.descripcion(),f.fechaCarga(),f.fechaCaptura())).toList());}}
